// --- Field order test (exact byte comparison since marshalOrdered is deterministic) ---

func TestCompact_FieldOrder(t *testing.T) {
	t.Parallel()

	input := []byte(`{"type":"user","uuid":"u1","timestamp":"2026-01-01T00:00:00Z","message":{"content":"hello"}}
`)

