func TestCompact_StartLineBeyondEnd(t *testing.T) {
	t.Parallel()

	input := []byte(`{"type":"user","uuid":"u1","timestamp":"t1","message":{"content":"hello"}}
`)
	opts := CompactOptions{Agent: "claude-code", CLIVersion: "0.5.1", StartLine: 100}

