		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"t3","content":"cursor user"}`,
		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"assistant","ts":"t4","content":[{"type":"text","text":"cursor assistant"}]}`,
		`{"v":1,"agent":"claude-code","cli_version":"0.5.1","type":"user","ts":"t5","content":"human alias"}`,
	}

