 29→// flattens the message wrapper, and splits user tool results into separate entries:
 30→//
 31→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 32→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user_tool_result","ts":"...","tool_use_id":"...","result":{...}}
 33→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[...]}
 34→func Compact(content []byte, opts CompactOptions) ([]byte, error) {
 35→	truncated := SliceFromLine(content, opts.StartLine)
 36→	if truncated == nil {
 37→		truncated = []byte{}
 38→	}
 39→
 40→	reader := bufio.NewReader(bytes.NewReader(truncated))
 41→	var result []byte
 42→
 43→	for {
 44→		lineBytes, err := reader.ReadBytes('\n')
 45→		if err != nil && err != io.EOF {
 46→			return nil, err
 47→		}
 48→
 49→		if len(bytes.TrimSpace(lineBytes)) > 0 {
 50→			outputLines := convertLine(lineBytes, opts)
 51→			for _, ol := range outputLines {
 52→				result = append(result, ol...)
 53→				result = append(result, '\n')
 54→			}
 55→		}
 56→
 57→		if err == io.EOF {
 58→			break
 59→		}
 60→	}
 61→
 62→	return result, nil
 63→}
 64→
 65→// userAliases maps transcript type/role values to the canonical "user" kind.
 66→var userAliases = map[string]bool{
 67→	"user":  true,
 68→	"human": true,
 69→}
 70→
 71→// assistantAliases maps transcript type/role values to the canonical "assistant" kind.
 72→var assistantAliases = map[string]bool{
 73→	"assistant": true,
 74→}
 75→
 76→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 77→// transcript line. It prefers the "type" field, then falls back to "role".
 78→// Returns "" for unrecognised or dropped entries.
 79→func normalizeKind(raw map[string]json.RawMessage) string {
 80→	// Try "type" first, then "role".
 81→	kind := unquote(raw["type"])
 82→	if kind == "" {
 83→		kind = unquote(raw["role"])
 84→	}
 85→
 86→	if droppedTypes[kind] {
 87→		return ""
 88→	}
 89→	if userAliases[kind] {
 90→		return "user"
 91→	}
 92→	if assistantAliases[kind] {
 93→		return "assistant"
 94→	}
 95→	return ""
 96→}
 97→
 98→// convertLine converts a single full.jsonl line into zero or more transcript.jsonl lines.
 99→// A user entry with tool_result blocks produces multiple output lines.
100→func convertLine(lineBytes []byte, opts CompactOptions) [][]byte {
101→	var raw map[string]json.RawMessage
102→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
103→		return nil
104→	}
105→
106→	switch normalizeKind(raw) {
107→	case "assistant":
108→		return convertAssistant(raw, opts)
109→	case "user":
110→		return convertUser(raw, opts)
111→	default:
112→		return nil // drop unknown types in the new format
113→	}
114→}
115→
116→func convertAssistant(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
117→	// Hoist id and content from message to top level
118→	var id, content json.RawMessage
119→	if msgRaw, ok := raw["message"]; ok {
120→		var msg map[string]json.RawMessage
121→		if json.Unmarshal(msgRaw, &msg) == nil {
122→			id = msg["id"]
123→			if contentRaw, ok := msg["content"]; ok {
124→				content = stripAssistantContent(contentRaw)
125→			}
126→		}
127→	}
128→
129→	b := marshalOrdered(
130→		"v", mustMarshal(1),
131→		"agent", mustMarshal(opts.Agent),
132→		"cli_version", mustMarshal(opts.CLIVersion),
133→		"type", mustMarshal("assistant"),
134→		"ts", raw["timestamp"],
135→		"id", id,
136→		"content", content,
137→	)
138→	if b == nil {
139→		return nil
140→	}
141→	return [][]byte{b}
142→}
143→
144→func convertUser(raw map[string]json.RawMessage, opts CompactOptions) [][]byte {
145→	var lines [][]byte
146→	ts := raw["timestamp"]
147→
148→	// Parse message content to separate text from tool_results
149→	var textContent string
150→	var toolResults []toolResultEntry
151→
152→	if msgRaw, ok := raw["message"]; ok {
153→		var msg map[string]json.RawMessage
154→		if json.Unmarshal(msgRaw, &msg) == nil {
155→			if contentRaw, ok := msg["content"]; ok {
156→				textContent, toolResults = extractUserContent(contentRaw)
157→			}
158→		}
159→	}
160→
161→	// Emit the user text entry
162→	b := marshalOrdered(
163→		"v", mustMarshal(1),
164→		"agent", mustMarshal(opts.Agent),
165→		"cli_version", mustMarshal(opts.CLIVersion),
166→		"type", mustMarshal("user"),
167→		"ts", ts,
168→		"content", mustMarshal(textContent),
169→	)
170→	if b != nil {
171→		lines = append(lines, b)
172→	}
173→
174→	// Emit separate user_tool_result entries.
175→	//
176→	// Note: full.jsonl has a single toolUseResult per user entry, not one per tool_use_id.
177→	// When there are multiple tool_result blocks, each user_tool_result line gets the same
178→	// minimized result. This is a known limitation of the source format — per-tool-use-id
179→	// result data is not available.
180→	var minimizedResult json.RawMessage
181→	if turRaw, ok := raw["toolUseResult"]; ok {
182→		minimizedResult = minimizeToolUseResult(turRaw)
183→	}
184→
185→	for _, tr := range toolResults {
186→		result := minimizedResult
187→		if result == nil {
188→			result = mustMarshal(map[string]interface{}{})
189→		}
190→
191→		b := marshalOrdered(
192→			"v", mustMarshal(1),
193→			"agent", mustMarshal(opts.Agent),
194→			"cli_version", mustMarshal(opts.CLIVersion),
195→			"type", mustMarshal("user_tool_result"),
196→			"ts", ts,
197→			"tool_use_id", mustMarshal(tr.toolUseID),
198→			"result", result,
199→		)
200→		if b != nil {
201→			lines = append(lines, b)
202→		}
203→	}
204→
205→	return lines
206→}
207→
208→type toolResultEntry struct {
209→	toolUseID string
210→}
211→
212→// extractUserContent separates user message content into text and tool_result entries.
213→func extractUserContent(contentRaw json.RawMessage) (string, []toolResultEntry) {
214→	// String content
215→	var str string
216→	if json.Unmarshal(contentRaw, &str) == nil {
217→		return str, nil
218→	}
219→
220→	// Array content
221→	var blocks []map[string]json.RawMessage
222→	if json.Unmarshal(contentRaw, &blocks) != nil {
223→		return "", nil
224→	}
225→
226→	var texts []string
227→	var toolResults []toolResultEntry
228→
229→	for _, block := range blocks {
230→		blockType := unquote(block["type"])
231→
232→		if blockType == "tool_result" {
233→			toolResults = append(toolResults, toolResultEntry{
234→				toolUseID: unquote(block["tool_use_id"]),
235→			})
236→			continue
237→		}
238→
239→		if blockType == "text" {
240→			texts = append(texts, unquote(block["text"]))
241→		}
242→	}
243→
244→	text := ""
245→	if len(texts) > 0 {
246→		text = texts[0]
247→		var textSb246 strings.Builder
248→		for i := 1; i < len(texts); i++ {
249→			textSb246.WriteString("\n\n" + texts[i])
250→		}
251→		text += textSb246.String()
252→	}
253→
254→	return text, toolResults
255→}
256→
257→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
258→	// String content — keep as-is
259→	var str string
260→	if json.Unmarshal(contentRaw, &str) == nil {
261→		return contentRaw
262→	}
263→
264→	// Array of content blocks
265→	var blocks []map[string]json.RawMessage
266→	if json.Unmarshal(contentRaw, &blocks) != nil {
267→		return contentRaw
268→	}
269→
270→	var result []map[string]json.RawMessage
271→	for _, block := range blocks {
272→		blockType := unquote(block["type"])
273→
274→		// Drop thinking blocks
275→		if blockType == "thinking" || blockType == "redacted_thinking" {
276→			continue
277→		}
278→
279→		// Strip tool_use: keep type, id, name, input — drop caller
280→		if blockType == "tool_use" {
281→			stripped := make(map[string]json.RawMessage)
282→			copyField(stripped, block, "type")
283→			copyField(stripped, block, "id")
284→			copyField(stripped, block, "name")
285→			copyField(stripped, block, "input")
286→			result = append(result, stripped)
287→			continue
288→		}
289→
290→		// Other block types (text, image) — keep as-is
291→		result = append(result, block)
292→	}
293→
294→	b, err := json.Marshal(result)
295→	if err != nil {
296→		return contentRaw
297→	}
298→	return b
299→}
300→
301→// minimizeToolUseResult strips a toolUseResult to only the fields the API needs.
302→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
303→	var obj map[string]json.RawMessage
304→	if json.Unmarshal(raw, &obj) != nil {
305→		return raw
306→	}
307→
308→	return marshalOrdered(
309→		"type", obj["type"],
310→		"file", obj["file"],
311→		"error", obj["error"],
312→		"answers", obj["answers"],
313→	)
314→}
315→
316→// marshalOrdered produces a JSON object with keys in the given order.
317→// Pairs with nil values are omitted.
318→func marshalOrdered(pairs ...interface{}) []byte {
319→	var buf bytes.Buffer
320→	buf.WriteByte('{')
321→	first := true
322→	for i := 0; i < len(pairs)-1; i += 2 {
323→		key := pairs[i].(string)
324→		val, _ := pairs[i+1].(json.RawMessage)
325→		if val == nil {
326→			continue
327→		}
328→		if !first {
329→			buf.WriteByte(',')
330→		}
331→		keyJSON, _ := json.Marshal(key)
332→		buf.Write(keyJSON)
333→		buf.WriteByte(':')
334→		buf.Write(val)
335→		first = false
336→	}
337→	buf.WriteByte('}')
338→	return buf.Bytes()
339→}
340→
341→func mustMarshal(v interface{}) json.RawMessage {
342→	b, _ := json.Marshal(v)
343→	return b
344→}
345→
346→func copyField(dst, src map[string]json.RawMessage, key string) {
347→	if v, ok := src[key]; ok {
348→		dst[key] = v
349→	}
350→}
351→
352→func unquote(raw json.RawMessage) string {
353→	var s string
354→	if json.Unmarshal(raw, &s) == nil {
355→		return s
356→	}
357→	return ""
358→}
