  1→package factoryaidroid
  2→
  3→import (
  4→	"bufio"
  5→	"bytes"
  6→	"encoding/json"
  7→	"fmt"
  8→	"io"
  9→	"log/slog"
 10→	"os"
 11→	"path/filepath"
 12→	"slices"
 13→	"strings"
 14→
 15→	"github.com/entireio/cli/cmd/entire/cli/agent"
 16→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 17→)
 18→
 19→// TranscriptLine is an alias to the shared transcript.Line type.
 20→type TranscriptLine = transcript.Line
 21→
 22→// droidEnvelope is the top-level structure of a Factory AI Droid JSONL line.
 23→// Droid wraps messages as {"type":"message","id":"...","message":{"role":"assistant","content":[...]}},
 24→// unlike Claude Code which uses {"type":"assistant","uuid":"...","message":{"content":[...]}}.
 25→type droidEnvelope struct {
 26→	Type    string          `json:"type"`
 27→	ID      string          `json:"id"`
 28→	Message json.RawMessage `json:"message"`
 29→}
 30→
 31→// droidMessageRole extracts just the role from the inner message.
 32→type droidMessageRole struct {
 33→	Role string `json:"role"`
 34→}
 35→
 36→// ParseDroidTranscript parses a Droid JSONL file into normalized transcript.Line entries.
 37→// It transforms the Droid envelope format (type="message", role inside message) into the
 38→// shared transcript.Line format (type="assistant"/"user", message=inner content).
 39→// Non-message entries (session_start, etc.) are skipped.
 40→func ParseDroidTranscript(path string, startLine int) ([]transcript.Line, int, error) {
 41→	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
 42→	if err != nil {
 43→		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
 44→	}
 45→	defer func() { _ = file.Close() }()
 46→
 47→	return parseDroidTranscriptFromReader(file, startLine)
 48→}
 49→
 50→// ParseDroidTranscriptFromBytes parses Droid JSONL content from a byte slice.
 51→// startLine skips the first N raw JSONL lines before parsing (0 = parse all).
 52→// Returns parsed lines, total raw line count, and any error.
 53→// This mirrors ParseDroidTranscript's startLine parameter, applying the offset
 54→// at the raw line level before filtering out non-message entries.
 55→func ParseDroidTranscriptFromBytes(content []byte, startLine int) ([]transcript.Line, int, error) {
 56→	return parseDroidTranscriptFromReader(bytes.NewReader(content), startLine)
 57→}
 58→
 59→func parseDroidTranscriptFromReader(r io.Reader, startLine int) ([]transcript.Line, int, error) {
 60→	reader := bufio.NewReader(r)
 61→	var lines []transcript.Line
 62→	totalLines := 0
 63→
 64→	for {
 65→		lineBytes, err := reader.ReadBytes('\n')
 66→		if err != nil && err != io.EOF {
 67→			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
 68→		}
 69→
 70→		if len(lineBytes) == 0 {
 71→			if err == io.EOF {
 72→				break
 73→			}
 74→			continue
 75→		}
 76→
 77→		if totalLines >= startLine {
 78→			if line, ok := parseDroidLine(lineBytes); ok {
 79→				lines = append(lines, line)
 80→			}
 81→		}
 82→		totalLines++
 83→
 84→		if err == io.EOF {
 85→			break
 86→		}
 87→	}
 88→
 89→	return lines, totalLines, nil
 90→}
 91→
 92→// parseDroidLine converts a single Droid JSONL line into a normalized transcript.Line.
 93→// Returns false if the line is not a message entry (e.g., session_start).
 94→func parseDroidLine(lineBytes []byte) (transcript.Line, bool) {
 95→	var env droidEnvelope
 96→	if err := json.Unmarshal(lineBytes, &env); err != nil {
 97→		return transcript.Line{}, false
 98→	}
 99→
100→	// Only process "message" type entries — skip session_start, etc.
101→	if env.Type != "message" {
102→		return transcript.Line{}, false
103→	}
104→
105→	// Extract role from the inner message
106→	var role droidMessageRole
107→	if err := json.Unmarshal(env.Message, &role); err != nil {
108→		return transcript.Line{}, false
109→	}
110→
111→	return transcript.Line{
112→		Type:    role.Role, // "assistant" or "user"
113→		UUID:    env.ID,
114→		Message: env.Message,
115→	}, true
116→}
117→
118→// ExtractModifiedFiles extracts files modified by tool calls from transcript.
119→func ExtractModifiedFiles(lines []TranscriptLine) []string {
120→	fileSet := make(map[string]bool)
121→	var files []string
122→
123→	for _, line := range lines {
124→		if line.Type != "assistant" {
125→			continue
126→		}
127→
128→		var msg transcript.AssistantMessage
129→		if err := json.Unmarshal(line.Message, &msg); err != nil {
130→			continue
131→		}
132→
133→		for _, block := range msg.Content {
134→			if block.Type != "tool_use" || !slices.Contains(FileModificationTools, block.Name) {
135→				continue
136→			}
137→
138→			var input transcript.ToolInput
139→			if err := json.Unmarshal(block.Input, &input); err != nil {
140→				continue
141→			}
142→
143→			file := input.FilePath
144→			if file == "" {
145→				file = input.NotebookPath
146→			}
147→
148→			if file != "" && !fileSet[file] {
149→				fileSet[file] = true
150→				files = append(files, file)
151→			}
152→		}
153→	}
154→
155→	return files
156→}
157→
158→// CalculateTokenUsage calculates token usage from a Factory AI Droid transcript.
159→// Due to streaming, multiple transcript rows may share the same message.id.
160→// We deduplicate by taking the row with the highest output_tokens for each message.id.
161→func CalculateTokenUsage(transcriptLines []TranscriptLine) *agent.TokenUsage {
162→	// Map from message.id to the usage with highest output_tokens
163→	usageByMessageID := make(map[string]messageUsage)
164→
165→	for _, line := range transcriptLines {
166→		if line.Type != "assistant" {
167→			continue
168→		}
169→
170→		var msg messageWithUsage
171→		if err := json.Unmarshal(line.Message, &msg); err != nil {
172→			continue
173→		}
174→
175→		if msg.ID == "" {
176→			continue
177→		}
178→
179→		// Keep the entry with highest output_tokens (final streaming state)
180→		existing, exists := usageByMessageID[msg.ID]
181→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
182→			usageByMessageID[msg.ID] = msg.Usage
183→		}
184→	}
185→
186→	// Sum up all unique messages
187→	usage := &agent.TokenUsage{
188→		APICallCount: len(usageByMessageID),
189→	}
190→	for _, u := range usageByMessageID {
191→		usage.InputTokens += u.InputTokens
192→		usage.CacheCreationTokens += u.CacheCreationInputTokens
193→		usage.CacheReadTokens += u.CacheReadInputTokens
194→		usage.OutputTokens += u.OutputTokens
195→	}
196→
197→	return usage
198→}
199→
200→// CalculateTokenUsageFromFile calculates token usage from a transcript file.
201→// If startLine > 0, only considers lines from startLine onwards.
202→func CalculateTokenUsageFromFile(path string, startLine int) (*agent.TokenUsage, error) {
203→	if path == "" {
204→		return &agent.TokenUsage{}, nil
205→	}
206→
207→	lines, _, err := ParseDroidTranscript(path, startLine)
208→	if err != nil {
209→		return nil, err
210→	}
211→
212→	return CalculateTokenUsage(lines), nil
213→}
214→
215→// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
216→// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
217→// Returns a map of agentID -> toolUseID for all spawned agents.
218→func ExtractSpawnedAgentIDs(transcriptLines []TranscriptLine) map[string]string {
219→	agentIDs := make(map[string]string)
220→
221→	for _, line := range transcriptLines {
222→		if line.Type != "user" {
223→			continue
224→		}
225→
226→		// Parse as array of content blocks (tool results)
227→		var contentBlocks []struct {
228→			Type      string          `json:"type"`
229→			ToolUseID string          `json:"tool_use_id"`
230→			Content   json.RawMessage `json:"content"`
231→		}
232→
233→		var msg struct {
234→			Content json.RawMessage `json:"content"`
235→		}
236→		if err := json.Unmarshal(line.Message, &msg); err != nil {
237→			continue
238→		}
239→
240→		if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
241→			continue
242→		}
243→
244→		for _, block := range contentBlocks {
245→			if block.Type != "tool_result" {
246→				continue
247→			}
248→
249→			// Content can be a string or array of text blocks
250→			var textContent string
251→
252→			// Try as array of text blocks first
253→			var textBlocks []struct {
254→				Type string `json:"type"`
255→				Text string `json:"text"`
256→			}
257→			if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
258→				var sb strings.Builder
259→				for _, tb := range textBlocks {
260→					if tb.Type == "text" {
261→						sb.WriteString(tb.Text + "\n")
262→					}
263→				}
264→				textContent = sb.String()
265→			} else {
266→				// Try as plain string
267→				var str string
268→				if err := json.Unmarshal(block.Content, &str); err == nil {
269→					textContent = str
270→				}
271→			}
272→
273→			// Look for agentId in the text
274→			if agentID := extractAgentIDFromText(textContent); agentID != "" {
275→				agentIDs[agentID] = block.ToolUseID
276→			}
277→		}
278→	}
279→
280→	return agentIDs
281→}
282→
283→// droidSettings represents the .settings.json file that Factory AI Droid
284→// stores alongside each session transcript JSONL.
285→type droidSettings struct {
286→	Model string `json:"model"`
287→}
288→
289→// ExtractModelFromTranscript extracts the LLM model name from the Factory AI Droid
290→// session settings file. Factory AI Droid stores a .settings.json file alongside
291→// each transcript JSONL (e.g., <session-id>.settings.json next to <session-id>.jsonl).
292→// The settings file contains the actual model being used, unlike the transcript's
293→// system-reminder text which can be stale after provider switches.
294→// Returns empty string if the settings file cannot be read or has no model.
295→func ExtractModelFromTranscript(transcriptPath string) string {
296→	if transcriptPath == "" {
297→		return ""
298→	}
299→
300→	settingsPath := strings.TrimSuffix(transcriptPath, ".jsonl") + ".settings.json"
301→	data, err := os.ReadFile(settingsPath) //nolint:gosec // Path derived from agent hook input
302→	if err != nil {
303→		return ""
304→	}
305→
306→	var settings droidSettings
307→	if err := json.Unmarshal(data, &settings); err != nil {
308→		slog.Warn("corrupt settings file, cannot extract model",
309→			slog.String("path", settingsPath),
310→			slog.Any("error", err))
311→		return ""
312→	}
313→
314→	return cleanModelName(settings.Model)
315→}
316→
317→// cleanModelName normalizes a Factory AI Droid model identifier into a display name.
318→// For example, "custom:Gemini-2.5-Pro-0" becomes "Gemini-2.5-Pro-0".
319→func cleanModelName(raw string) string {
320→	// Strip known prefixes that Factory AI Droid adds to model identifiers
321→	if after, found := strings.CutPrefix(raw, "custom:"); found {
322→		return after
323→	}
324→	return raw
325→}
326→
327→// extractAgentIDFromText extracts an agent ID from text containing "agentId: <id>".
328→func extractAgentIDFromText(text string) string {
329→	const prefix = "agentId: "
330→	idx := strings.Index(text, prefix)
331→	if idx == -1 {
332→		return ""
333→	}
334→
335→	// Extract the ID (alphanumeric characters after the prefix)
336→	start := idx + len(prefix)
337→	end := start
338→	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' ||
339→		text[end] >= 'A' && text[end] <= 'Z' ||
340→		text[end] >= '0' && text[end] <= '9') {
341→		end++
342→	}
343→
344→	if end > start {
345→		return text[start:end]
346→	}
347→	return ""
348→}
349→
350→// CalculateTotalTokenUsageFromBytes calculates token usage from pre-loaded transcript bytes,
351→// including subagents. It parses the main transcript bytes from startLine, extracts spawned
352→// agent IDs, and calculates their token usage from transcript files in subagentsDir.
353→func CalculateTotalTokenUsageFromBytes(data []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
354→	if len(data) == 0 {
355→		return &agent.TokenUsage{}, nil
356→	}
357→
358→	parsed, _, err := ParseDroidTranscriptFromBytes(data, startLine)
359→	if err != nil {
360→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
361→	}
362→
363→	mainUsage := CalculateTokenUsage(parsed)
364→
365→	agentIDs := ExtractSpawnedAgentIDs(parsed)
366→	if len(agentIDs) > 0 && subagentsDir != "" {
367→		subagentUsage := &agent.TokenUsage{}
368→		for agentID := range agentIDs {
369→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
370→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
371→			if err != nil {
372→				continue
373→			}
374→			subagentUsage.InputTokens += agentUsage.InputTokens
375→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
376→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
377→			subagentUsage.OutputTokens += agentUsage.OutputTokens
378→			subagentUsage.APICallCount += agentUsage.APICallCount
379→		}
380→		if subagentUsage.APICallCount > 0 {
381→			mainUsage.SubagentTokens = subagentUsage
382→		}
383→	}
384→
385→	return mainUsage, nil
386→}
387→
388→// ExtractAllModifiedFilesFromBytes extracts files modified by both the main agent and
389→// any subagents from pre-loaded transcript bytes. It parses the main transcript bytes from
390→// startLine, collects modified files, then reads each subagent's transcript from
391→// subagentsDir to collect their modified files too.
392→func ExtractAllModifiedFilesFromBytes(data []byte, startLine int, subagentsDir string) ([]string, error) {
393→	if len(data) == 0 {
394→		return nil, nil
395→	}
396→
397→	parsed, _, err := ParseDroidTranscriptFromBytes(data, startLine)
398→	if err != nil {
399→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
400→	}
401→
402→	files := ExtractModifiedFiles(parsed)
403→	fileSet := make(map[string]bool, len(files))
404→	for _, f := range files {
405→		fileSet[f] = true
406→	}
407→
408→	agentIDs := ExtractSpawnedAgentIDs(parsed)
409→	if subagentsDir == "" {
410→		return files, nil
411→	}
412→	for agentID := range agentIDs {
413→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
414→		agentLines, _, agentErr := ParseDroidTranscript(agentPath, 0)
415→		if agentErr != nil {
416→			continue
417→		}
418→		for _, f := range ExtractModifiedFiles(agentLines) {
419→			if !fileSet[f] {
420→				fileSet[f] = true
421→				files = append(files, f)
422→			}
423→		}
424→	}
425→
426→	return files, nil
427→}
428→
429→// CalculateTotalTokenUsageFromTranscript calculates token usage for a turn, including subagents.
430→// It parses the main transcript from startLine, extracts spawned agent IDs,
431→// and calculates their token usage from transcripts in subagentsDir.
432→func CalculateTotalTokenUsageFromTranscript(transcriptPath string, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
433→	if transcriptPath == "" {
434→		return &agent.TokenUsage{}, nil
435→	}
436→
437→	// Parse transcript once using Droid-specific parser
438→	parsed, _, err := ParseDroidTranscript(transcriptPath, startLine)
439→	if err != nil {
440→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
441→	}
442→
443→	// Calculate token usage from parsed transcript
444→	mainUsage := CalculateTokenUsage(parsed)
445→
446→	// Extract spawned agent IDs from the same parsed transcript
447→	agentIDs := ExtractSpawnedAgentIDs(parsed)
448→
449→	// Calculate subagent token usage
450→	if len(agentIDs) > 0 {
451→		subagentUsage := &agent.TokenUsage{}
452→		for agentID := range agentIDs {
453→			agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
454→			agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
455→			if err != nil {
456→				// Agent transcript may not exist yet or may have been cleaned up
457→				continue
458→			}
459→			subagentUsage.InputTokens += agentUsage.InputTokens
460→			subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
461→			subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
462→			subagentUsage.OutputTokens += agentUsage.OutputTokens
463→			subagentUsage.APICallCount += agentUsage.APICallCount
464→		}
465→		if subagentUsage.APICallCount > 0 {
466→			mainUsage.SubagentTokens = subagentUsage
467→		}
468→	}
469→
470→	return mainUsage, nil
471→}
472→
473→// ExtractAllModifiedFilesFromTranscript extracts files modified by both the main agent and
474→// any subagents spawned via the Task tool. It parses the main transcript from
475→// startLine, collects modified files from the main agent, then reads each
476→// subagent's transcript from subagentsDir to collect their modified files too.
477→// The result is a deduplicated list of all modified file paths.
478→func ExtractAllModifiedFilesFromTranscript(transcriptPath string, startLine int, subagentsDir string) ([]string, error) {
479→	if transcriptPath == "" {
480→		return nil, nil
481→	}
482→
483→	// Parse main transcript once using Droid-specific parser
484→	parsed, _, err := ParseDroidTranscript(transcriptPath, startLine)
485→	if err != nil {
486→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
487→	}
488→
489→	// Collect modified files from main agent (already deduplicated)
490→	files := ExtractModifiedFiles(parsed)
491→	fileSet := make(map[string]bool, len(files))
492→	for _, f := range files {
493→		fileSet[f] = true
494→	}
495→
496→	// Find spawned subagents and collect their modified files
497→	agentIDs := ExtractSpawnedAgentIDs(parsed)
498→	for agentID := range agentIDs {
499→		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
500→		agentLines, _, agentErr := ParseDroidTranscript(agentPath, 0)
501→		if agentErr != nil {
502→			// Subagent transcript may not exist yet or may have been cleaned up
503→			continue
504→		}
505→		for _, f := range ExtractModifiedFiles(agentLines) {
506→			if !fileSet[f] {
507→				fileSet[f] = true
508→				files = append(files, f)
509→			}
510→		}
511→	}
512→
513→	return files, nil
514→}
