301→// minimizeToolUseResult strips a toolUseResult to only the fields the API needs.
302→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
303→	var obj map[string]json.RawMessage
304→	if json.Unmarshal(raw, &obj) != nil {
305→		return raw
306→	}
307→
308→	return marshalOrdered(
309→		"type", obj["type"],
310→		"file", obj["file"],
311→		"error", obj["error"],
312→		"answers", obj["answers"],
313→	)
314→}
315→
316→// marshalOrdered produces a JSON object with keys in the given order.
317→// Pairs with nil values are omitted.
318→func marshalOrdered(pairs ...interface{}) []byte {
319→	var buf bytes.Buffer
320→	buf.WriteByte('{')
321→	first := true
322→	for i := 0; i < len(pairs)-1; i += 2 {
323→		key := pairs[i].(string)
324→		val, _ := pairs[i+1].(json.RawMessage)
325→		if val == nil {
326→			continue
327→		}
328→		if !first {
329→			buf.WriteByte(',')
330→		}
331→		keyJSON, _ := json.Marshal(key)
332→		buf.Write(keyJSON)
333→		buf.WriteByte(':')
334→		buf.Write(val)
335→		first = false
336→	}
337→	buf.WriteByte('}')
338→	return buf.Bytes()
339→}
340→
341→func mustMarshal(v interface{}) json.RawMessage {
342→	b, _ := json.Marshal(v)
343→	return b
344→}
345→
346→func copyField(dst, src map[string]json.RawMessage, key string) {
347→	if v, ok := src[key]; ok {
348→		dst[key] = v
349→	}
350→}
351→
352→func unquote(raw json.RawMessage) string {
353→	var s string
354→	if json.Unmarshal(raw, &s) == nil {
355→		return s
356→	}
357→	return ""
358→}
