 80→+var assistantAliases = map[string]bool{
 81→+	"assistant": true,
 82→+	"gemini":    true,
 83→+}
 84→+
 85→+// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
 86→+// transcript line. It checks the "type" field, then falls back to "role".
 87→+// Returns "" for unrecognised or dropped entries.
 88→+func normalizeKind(raw map[string]json.RawMessage) string {
 89→+	// Try "type" first, then "role".
 90→+	kind := unquote(raw["type"])
 91→+	if kind == "" {
 92→+		kind = unquote(raw["role"])
 93→+	}
 94→+
 95→+	if droppedTypes[kind] {
