 97→+	}
 98→+	if userAliases[kind] {
 99→+		return "user"
100→+	}
101→+	if assistantAliases[kind] {
102→+		return "assistant"
103→+	}
104→+	return ""
105→+}
106→+
107→+// unwrapEnvelope handles envelope formats where the actual message is nested.
108→+// Factory AI Droid uses {"type":"message","message":{"role":"user","content":...}}.
109→+// If the line is an envelope, it returns the inner message merged with outer fields
110→+// (timestamp, id). Otherwise it returns raw unchanged.
111→+func unwrapEnvelope(raw map[string]json.RawMessage) map[string]json.RawMessage {
112→+	kind := unquote(raw["type"])
113→+	if kind != "message" {
114→+		return raw
115→+	}
116→+
117→+	msgRaw, ok := raw["message"]
118→+	if !ok {
119→+		return raw
120→+	}
121→+
122→+	var inner map[string]json.RawMessage
123→+	if json.Unmarshal(msgRaw, &inner) != nil {
124→+		return raw
125→+	}
126→+
127→+	// The inner message should have a "role" field — check it resolves to a known kind.
128→+	innerRole := unquote(inner["role"])
129→+	if !userAliases[innerRole] && !assistantAliases[innerRole] {
130→+		return raw
131→+	}
132→+
133→+	// Build a merged view: inner fields take precedence, but carry over outer
134→+	// fields (timestamp, id) that the inner message may lack.
135→+	merged := make(map[string]json.RawMessage, len(inner)+2)
136→+	// Copy outer timestamp if present.
137→+	if v, has := raw["timestamp"]; has {
138→+		merged["timestamp"] = v
139→+	}
140→+	// Copy outer id as fallback.
141→+	if v, has := raw["id"]; has {
142→+		merged["id"] = v
143→+	}
144→+	// Copy all inner fields (overrides outer if keys collide).
145→+	for k, v := range inner {
146→+		merged[k] = v
147→+	}
148→+	// Promote "role" to "type" so normalizeKind resolves it.
149→+	if _, hasType := merged["type"]; !hasType {
150→+		merged["type"] = inner["role"]
151→+	}
152→+
153→+	// Re-wrap content into a "message" field so converters find it.
154→+	// The inner message IS the message wrapper for converters.
