+	// fields (timestamp, id) that the inner message may lack.
+	merged := make(map[string]json.RawMessage, len(inner)+2)
+	// Copy outer timestamp if present.
+	if v, has := raw["timestamp"]; has {
+		merged["timestamp"] = v
+	}
+	// Copy outer id as fallback.
+	if v, has := raw["id"]; has {
+		merged["id"] = v
+	}
